{
  "changed": [
    {
      "change": "In Next.js 16 middleware.ts is renamed to proxy.ts, and the file and its exported function are renamed to proxy. The logic stays the same, but middleware.ts is deprecated and will be removed in a future version.",
      "lesson": 3
    },
    {
      "change": "In Next.js 16 synchronous access to params is removed, so a page must await params before it reads params.slug.",
      "lesson": 4
    },
    {
      "change": "In Next.js 16 revalidateTag() requires a cacheLife profile as its second argument, for example revalidateTag('posts', 'max'). A Server Action that must read its own write can call updateTag() instead.",
      "lesson": 5
    },
    {
      "change": "In Next.js 16 the next lint command is removed and next build no longer runs linting. Use ESLint or Biome directly, and a codemod named next-lint-to-eslint-cli is available.",
      "lesson": 7
    }
  ],
  "whatsNew": {
    "level": "intermediate",
    "offer": "Learn to turn on Cache Components and use updateTag() so your app shows fresh data after a save in Next.js 16.",
    "skills": [
      {
        "description": "Turn on cacheComponents: true to use Partial Pre-Rendering and use cache for instant navigation.",
        "name": "Enable Cache Components in next.config.ts"
      },
      {
        "description": "Call updateTag() in a Server Action so the cache expires and the same request reads the new data.",
        "name": "Read fresh data right after a save"
      },
      {
        "description": "Call refresh() to reload only uncached data without touching cached content.",
        "name": "Refresh uncached data with refresh()"
      }
    ],
    "title": "What's new in Next.js 16"
  }
}

